"""Shipping helpers: zone lookup, cost calculation, and oversize check."""


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    DE -> 1, FR or NL -> 2, anything else -> 3.
    """
    if country_code == "DE":
        return 1
    if country_code in ("FR", "NL"):
        return 2
    return 3


_BASE_BY_ZONE = {1: 6.0, 2: 15.0, 3: 30.0}


def shipping_cost(weight_kg, zone):
    """Return base + 0.8 * weight_kg, rounded to 2 decimals.

    Base is 6.0 for zone 1, 15.0 for zone 2 and 30.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 0.8 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 150 or l + w + h exceeds 360."""
    return l > 150 or w > 150 or h > 150 or (l + w + h) > 360

